[p, q] = [q, p];
console.log(p, q); // "prawo" "lewo"

function minMax(arr) {
  return [Math.min(...arr), Math.max(...arr)];
}

const [min, max] = minMax([4, 1, 9, 2, 7]);
console.log(min, max); // 1 9

