  return [25, "Kasia"];
}

const [wiek, imie] = pobierzDane();
console.log(imie, wiek); // 'Kasia' 25 - POPRAWNIE

function podzielTablice(tablica) {
  const srodek = Math.floor(tablica.length / 2);
  return [tablica.slice(0, srodek), tablica.slice(srodek)];
}

const [pierwszaPolowa, drugaPolowa] = podzielTablice([1, 2, 3, 4, 5, 6]);
console.log(pierwszaPolowa); // [1, 2, 3]
console.log(drugaPolowa);    // [4, 5, 6]

const [para1, para2] = [[1, 2], [3, 4]];
console.log(para1); // [1, 2]
console.log(para2); // [3, 4]

function wspolrzedne() {
  return [10, 20, 30];
}

const [x, , z] = wspolrzedne();
console.log(x, z); // 10 30

const [pierwszy, ...reszta] = [1, 2, 3, 4, 5];
const ostatni = reszta.at(-1);
console.log(pierwszy, ostatni); // 1 5

function minMaxSuma(arr) {
  return [Math.min(...arr), Math.max(...arr), arr.reduce((a, b) => a + b, 0)];
}

const [min, max, suma] = minMaxSuma([3, 7, 1, 9, 4]);
console.log(min, max, suma); // 1 9 24

let a = 1, b = 2, c = 3;
[a, b, c] = [b, c, a];
console.log(a, b, c); // 2 3 1

const osoby = [["Jan", 25], ["Ala", 30]];
osoby.forEach(([imie, wiek]) => {
  console.log(`${imie} ma ${wiek} lat`);
});
// Jan ma 25 lat
// Ala ma 30 lat

function test(tablica) {
  const [status = "nieznany"] = tablica;
  return status;
}

console.log(test([]));            // "nieznany"
console.log(test(["aktywny"]));   // "aktywny"

const [pierwsza, ...reszta] = "Hello".split("");
console.log(pierwsza); // "H"
console.log(reszta);   // ['e', 'l', 'l', 'o']

const kwoty = [100, 50, 75, 25];
const [pierwszaKwota, ...pozostaleKwoty] = kwoty;

console.log(pierwszaKwota);   // 100
console.log(pozostaleKwoty);  // [50, 75, 25]

function pierwszyIOstatni(tablica) {
  return [tablica[0], tablica.at(-1)];
}

const [pierwszy, ostatni] = pierwszyIOstatni([10, 20, 30, 40]);
console.log(pierwszy, ostatni); // 10 40

const pary = [["a", 1], ["b", 2]];
for (const [klucz, wartosc] of pary) {
  console.log(`${klucz} = ${wartosc}`);
}
// a = 1
// b = 2

function pierwszeDwaINastepne([a, b, ...reszta]) {
  return { pierwsze: [a, b], reszta };
}

console.log(pierwszeDwaINastepne([1, 2, 3, 4, 5]));
// { pierwsze: [1, 2], reszta: [3, 4, 5] }

const ranking = [95, 88, 82, 75, 60, 45];
const [z1, z2, z3, ...pozostali] = ranking;

console.log(z1, z2, z3); // 95 88 82
console.log(pozostali);  // [75, 60, 45]

function pierwszyElementLubDomyslny(tablica, domyslny) {
  const [pierwszy = domyslny] = tablica;
  return pierwszy;
}

console.log(pierwszyElementLubDomyslny([], "brak")); // "brak"
console.log(pierwszyElementLubDomyslny([42], "brak")); // 42

const tablica = [1, 2, 3];
const [a1, b1, c1] = tablica;
const [x2, y2, z2] = tablica;

console.log(a1, b1, c1); // 1 2 3
console.log(x2, y2, z2); // 1 2 3

function pobierzTop3(tablica) {
  const posortowane = [...tablica].sort((a, b) => b - a);
  return [posortowane[0], posortowane[1], posortowane[2]];
}

const [pierwsze, drugie, trzecie] = pobierzTop3([50, 20, 90, 10, 70]);
console.log(pierwsze, drugie, trzecie); // 90 70 50

